import openpyxl
wb = openpyxl.load_workbook('inputs/delivery.xlsx', data_only=False)
for ws in wb.worksheets:
    print('SHEET', ws.title, ws.max_row, ws.max_column)
    for r in range(1, min(ws.max_row, 14)+1):
        vals=[]
        for c in range(1, min(ws.max_column,2)+1):
            v=ws.cell(r,c).value
            vals.append((ws.cell(r,c).coordinate, repr(v), type(v).__name__))
        print(vals)

